{
  "appearance_facts": [
    {
      "location": "The map fills the left and center of the page, with the legend positioned on the right side.",
      "fact": "The chart is a choropleth map of the United States where each state is filled with a solid color corresponding to a value scale."
    },
    {
      "location": "The legend is a vertical bar located on the right side of the map, roughly between y=750 and y=1150.",
      "fact": "The legend displays a color gradient transitioning from a pale yellow at the top to a deep, dark red at the bottom."
    },
    {
      "location": "The state labeled 'PA' is located in the mid-Atlantic region, east of Ohio and west of New York.",
      "fact": "The state of Pennsylvania (PA) is filled with a very dark, deep red color, which is the darkest shade visible on the map."
    },
    {
      "location": "The state labeled 'NE' is located in the central region, west of Iowa and south of South Dakota.",
      "fact": "The state of Nebraska (NE) is filled with a dark red color, similar in intensity to the shade used for Pennsylvania."
    },
    {
      "location": "The state labeled 'NJ' is located on the east coast, south of New York and east of Pennsylvania.",
      "fact": "The state of New Jersey (NJ) is filled with a pale yellow color, indicating a value at the high end of the scale."
    },
    {
      "location": "The state labeled 'DE' is located on the east coast, south of Maryland and east of Pennsylvania.",
      "fact": "The state of Delaware (DE) is filled with a pale yellow color, similar to New Jersey and other southeastern states."
    },
    {
      "location": "Several states including CA, AZ, NM, and AR are filled with a solid light gray color.",
      "fact": "These gray states do not correspond to any color on the prevalence legend."
    }
  ],
  "printed_facts": [
    {
      "location": "The title is at the top left of the image.",
      "fact": "The chart title reads 'Prevalence of Species Z in US States'."
    },
    {
      "location": "The legend is on the right side of the map.",
      "fact": "The legend has a label 'High' at the top and 'Low' at the bottom."
    },
    {
      "location": "The numerical scale is to the right of the color bar.",
      "fact": "The legend scale ranges from 0 at the bottom to 100 at the top, with tick marks at 0, 20, 40, 60, 80, and 100."
    },
    {
      "location": "The color for the 'Low' end of the scale (0) is a deep, dark red.",
      "fact": "The darkest red color on the map corresponds to the lowest values on the scale (near 0)."
    },
    {
      "location": "The color for the 'High' end of the scale (100) is a pale yellow.",
      "fact": "The pale yellow color on the map corresponds to the highest values on the scale (near 100)."
    },
    {
      "location": "The state labeled 'PA' is colored with the darkest red.",
      "fact": "Pennsylvania (PA) is associated with a value near the 'Low' end of the scale (approx. 0-10)."
    },
    {
      "location": "The state labeled 'NJ' is colored pale yellow.",
      "fact": "New Jersey (NJ) is associated with a value near the 'High' end of the scale (approx. 90-100)."
    },
    {
      "location": "The state labeled 'DE' is colored pale yellow.",
      "fact": "Delaware (DE) is associated with a value near the 'High' end of the scale (approx. 90-100)."
    }
  ],
  "public_definitions": [
    "Routing criterion: Highest prevalence state in the dashboard",
    "Record workflow: State prevalence priority follow-up",
    "User goal: open the state prevalence record that should be routed into the highest-prevalence priority follow-up workflow."
  ],
